:root {
  --bg: #1a1c2c;
  --card: #2d2f45;
  --accent: #f4d35e;
  --text: #f0f0f5;
  --muted: #9a9cb5;
  --danger: #e4572e;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}
.card {
  width: 100%;
  max-width: 480px;
  background: var(--card);
  padding: 24px;
  border: 4px solid var(--accent);
  box-shadow: 8px 8px 0 #000;
}
h1 {
  margin: 0 0 16px;
  font-size: 1.5rem;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
}
.counters {
  display: flex;
  gap: 16px;
  margin-bottom: 16px;
  font-size: 1rem;
  color: var(--muted);
}
.counters strong { color: var(--text); }
.input-row { display: flex; gap: 8px; margin-bottom: 16px; }
input[type="text"] {
  flex: 1;
  min-width: 0;
  padding: 12px;
  font-size: 1rem;
  font-family: inherit;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--muted);
}
input[type="text"]:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
  border-color: var(--accent);
}
button {
  font-family: inherit;
  font-size: 1rem;
  padding: 12px 16px;
  cursor: pointer;
  background: var(--accent);
  color: var(--bg);
  border: 3px solid var(--accent);
  font-weight: 700;
  transition: transform 0.05s;
}
button:hover { background: #ffe27a; }
button:focus-visible { outline: 3px solid var(--text); outline-offset: 2px; }
button:active { transform: translate(2px, 2px); box-shadow: none; }
.todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.todo-list li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: var(--bg);
  border: 2px solid var(--muted);
}
.todo-list li.done span { text-decoration: line-through; color: var(--muted); }
.todo-list span { flex: 1; word-break: break-word; }
.todo-list input[type="checkbox"] {
  width: 24px;
  height: 24px;
  accent-color: var(--accent);
  cursor: pointer;
  flex-shrink: 0;
}
.todo-list button {
  padding: 6px 10px;
  background: var(--danger);
  border-color: var(--danger);
  color: var(--text);
  font-size: 0.875rem;
}
.todo-list button:hover { background: #f06a44; }
.visually-hidden {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
@media (max-width: 400px) {
  .card { padding: 16px; }
  .input-row { flex-direction: column; }
  .input-row button { width: 100%; }
}

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');

let nextId = 1;
const tasks = [];

function updateCounts() {
  totalEl.textContent = tasks.length;
  remainingEl.textContent = tasks.filter(t => !t.done).length;
}

function createTaskNode(task) {
  const li = document.createElement('li');
  li.dataset.id = task.id;
  if (task.done) li.classList.add('done');

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.id = `todo-check-${task.id}`;
  checkbox.checked = task.done;
  checkbox.setAttribute('aria-label', `Mark task ${task.id} complete`);

  const span = document.createElement('span');
  span.id = `todo-text-${task.id}`;
  span.textContent = task.text;

  const del = document.createElement('button');
  del.type = 'button';
  del.id = `todo-delete-${task.id}`;
  del.textContent = 'Delete';
  del.setAttribute('aria-label', `Delete task ${task.id}`);

  checkbox.addEventListener('change', () => {
    task.done = checkbox.checked;
    li.classList.toggle('done', task.done);
    updateCounts();
  });

  del.addEventListener('click', () => {
    const idx = tasks.indexOf(task);
    if (idx !== -1) tasks.splice(idx, 1);
    li.remove();
    updateCounts();
  });

  const label = document.createElement('label');
  label.htmlFor = checkbox.id;
  label.className = 'visually-hidden';
  label.textContent = `Toggle task ${task.id}`;

  li.append(checkbox, span, del);
  return li;
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  const task = { id: nextId++, text, done: false };
  tasks.push(task);
  list.appendChild(createTaskNode(task));
  input.value = '';
  updateCounts();
  input.focus();
}

addBtn.addEventListener('click', addTask);
input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') { e.preventDefault(); addTask(); }
});

updateCounts();
